import {uid} from './storage.js';
import {icon} from './icons.js';
import {$,$$,esc,openForm,option} from './ui.js';

const types=[['play','Tocar efeito'],['fade','Fade de camada'],['stop','Parar camada'],['music-play','Iniciar / trocar música'],['music-stop','Encerrar música'],['music-volume','Alterar volume da música'],['ambience','Ativar ambiente salvo'],['ambience-stop','Encerrar ambiente salvo'],['mix','Alterar canal do mixer'],['message','Mostrar lembrete ao mestre'],['navigate','Abrir página / cena']];
export function editCue(ctx,cue,back){
  const state=ctx.state(),scene=ctx.scene(),assets=state.audioAssets.filter(a=>!['youtube','spotify'].includes(a.provider));
  let actions=structuredClone(cue?.actions||[{type:'play',assetId:assets[0]?.id,volume:.8,delay:0}]);
  const campaign=state.campaigns.find(c=>c.id===state.ui.campaignId)||state.campaigns[0];
  const select=(key,label,options,value)=>`<label class="field"><span>${label}</span><select data-a="${key}">${options.map(([v,l])=>option(v,l,v===value)).join('')}</select></label>`;
  const input=(key,label,value=0,attributes='')=>`<label class="field"><span>${label}</span><input data-a="${key}" value="${esc(value)}" ${attributes}></label>`;
  const numeric='type="number" min="0" max="30" step="0.1" required';
  function controls(a){
    const duration=input('duration','Duração (s)',a.duration??2,numeric);
    const automatic=input('duration',a.type==='stop'?'Fade out (s)':'Transição (s)',a.duration??'','type="number" min="0" max="30" step="0.1" inputmode="decimal" placeholder="Padrão configurado"');
    if(a.type==='play')return select('assetId','Áudio',assets.map(x=>[x.id,x.name]),a.assetId)+input('volume','Volume (%)',Math.round((a.volume??.8)*100),'type="number" min="0" max="100" required')+'<div class="form-grid">'+input('fadeIn','Fade in (s)',a.fadeIn??'','type="number" min="0" max="30" step="0.1" inputmode="decimal" placeholder="Do áudio"')+input('fadeOut','Fade out (s)',a.fadeOut??'','type="number" min="0" max="30" step="0.1" inputmode="decimal" placeholder="Do áudio"')+'</div><p class="form-hint">Vazio usa os fades do áudio. A saída acontece antes do fim do arquivo. 0 desativa o fade.</p>';
    if(['fade','stop'].includes(a.type))return select('layerId','Camada da cena',scene.layers.map(x=>[x.id,x.name]),a.layerId)+(a.type==='fade'?'<div class="form-grid">'+input('to','Volume de destino (%)',Math.round((a.to??0)*100),'type="number" min="0" max="100" required')+duration+'</div>':automatic);
    if(a.type==='music-play')return select('source','Faixa ou playlist',[...state.audioAssets.map(x=>['asset:'+x.id,x.name+(x.provider==='youtube'?' · YouTube':x.provider==='spotify'?' · Spotify':'')]),...state.playlists.map(x=>['playlist:'+x.id,'Playlist · '+x.name])],a.playlistId?'playlist:'+a.playlistId:a.assetId?'asset:'+a.assetId:'')+'<div class="form-grid">'+input('fadeIn','Entrada (s)',a.fadeIn??state.settings.musicFadeIn,numeric)+input('fadeOut','Saída anterior (s)',a.fadeOut??state.settings.musicFadeOut,numeric)+'</div><div class="form-grid">'+input('volume','Volume (%)',Math.round((a.volume??1)*100),'type="number" min="0" max="100" required')+input('startSeconds','Começar em (s)',a.startSeconds||0,'type="number" min="0" step="1" required')+'</div>'+`<label class="check-field"><input type="checkbox" data-a="loop" ${a.loop!==false?'checked':''}><span>Repetir a música até trocar ou encerrar</span></label><p class="form-hint">Para faixas individuais. Playlists continuam sua sequência. A ação Iniciar / trocar música encerra a anterior. Spotify usa saída → carregamento → entrada, sem sobrepor músicas.</p>`+input('index','Primeira faixa da playlist',(a.index??a.youtubeIndex??0)+1,'type="number" min="1" step="1" required');
    if(a.type==='music-stop')return duration;
    if(a.type==='ambience-stop')return automatic;
    if(a.type==='music-volume')return '<div class="form-grid">'+input('to','Volume de destino (%)',Math.round((a.to??.5)*100),'type="number" min="0" max="100" required')+duration+'</div>';
    if(a.type==='ambience')return select('ambienceId','Ambiente salvo',(state.ambiences||[]).map(x=>[x.id,x.name]),a.ambienceId)+automatic;
    if(a.type==='mix')return select('group','Canal',[['master','Geral'],['music','Música / YouTube'],['ambience','Ambiências'],['sfx','Efeitos']],a.group||'master')+'<div class="form-grid">'+input('to','Volume de destino (%)',Math.round((a.to??.5)*100),'type="number" min="0" max="100" required')+duration+'</div>';
    if(a.type==='message')return `<label class="field"><span>Lembrete (visível só para o mestre)</span><textarea data-a="message" maxlength="800" required>${esc(a.message||'')}</textarea></label>`;
    if(a.type==='navigate')return select('destination','Página / cena',campaign.pages.flatMap(p=>p.scenes.map(s=>[p.id+'|'+s.id,p.title+' / '+s.title])),a.pageId&&a.sceneId?a.pageId+'|'+a.sceneId:'')+'<p class="form-hint">Abre o roteiro escolhido e mantém o áudio atual.</p>';
    return '';
  }
  function read(root){$$('.cue-action-row',root).forEach((row,i)=>{const a={...actions[i],type:$('[data-action-type]',row).value,delay:Number($('[data-delay]',row).value)};$$('[data-a]',row).forEach(el=>{const key=el.dataset.a;if(key==='loop')a.loop=el.checked;else if(['volume','to'].includes(key))a[key]=Number(el.value)/100;else if(key==='index')a.index=Math.max(0,Number(el.value)-1);else if(['duration','fadeIn','fadeOut','startSeconds'].includes(key))a[key]=el.value===''?undefined:Number(el.value);else a[key]=el.value;});
    if(a.source){const [type,...id]=a.source.split(':');a.assetId=type==='asset'?id.join(':'):null;a.playlistId=type==='playlist'?id.join(':'):null;delete a.source;}
    if(a.destination){[a.pageId,a.sceneId]=a.destination.split('|');delete a.destination;}
    if(a.type==='music-play')a.youtubeIndex=a.index||0;actions[i]=a;
  });}
  function render(root){$('#cueActions',root).innerHTML=actions.map((a,i)=>`<section class="cue-action-row"><div class="cue-action-heading"><b>AÇÃO ${i+1}</b><div><button type="button" class="icon-btn" data-up-action="${i}" aria-label="Mover ação para cima">↑</button><button type="button" class="icon-btn" data-remove-action="${i}" aria-label="Excluir ação">${icon('trash')}</button></div></div><div class="form-grid"><label class="field"><span>Ação</span><select data-action-type>${types.map(([v,l])=>option(v,l,v===a.type)).join('')}</select></label><label class="field"><span>Atraso desde o clique (s)</span><input data-delay type="number" min="0" max="3600" step="0.1" value="${Number(a.delay)||0}" required></label></div><div class="cue-action-fields">${controls(a)}</div></section>`).join('');
    $$('[data-action-type]',root).forEach(el=>el.onchange=()=>{read(root);render(root);});$$('[data-remove-action]',root).forEach(b=>b.onclick=()=>{read(root);actions.splice(+b.dataset.removeAction,1);render(root);});$$('[data-up-action]',root).forEach(b=>b.onclick=()=>{read(root);const i=+b.dataset.upAction;if(i>0)[actions[i-1],actions[i]]=[actions[i],actions[i-1]];render(root);});
  }
  openForm({title:cue?'Editar cue composta':'Nova cue composta',wide:true,body:`<label class="field"><span>Nome da cue</span><input name="name" value="${esc(cue?.name||'')}" required maxlength="100"></label><p class="form-hint">Combine música, ambientes, mixer, navegação e lembretes. O atraso de cada ação é contado desde o clique.</p><div id="cueActions"></div><button type="button" class="btn outline full" id="addCueAction">+ Adicionar ação</button>`,onReady:root=>{render(root);$('#addCueAction',root).onclick=()=>{read(root);actions.push({type:'play',assetId:assets[0]?.id,volume:.8,delay:0});render(root);};},onSubmit:form=>{
    read($('#dialogBody'));const name=String(form.get('name')).trim();if(!name)throw new Error('Informe um nome.');if(!actions.length)throw new Error('Adicione pelo menos uma ação.');
    for(const a of actions){if(a.type==='play'&&!a.assetId)throw new Error('Escolha o áudio da ação.');if(['fade','stop'].includes(a.type)&&!a.layerId)throw new Error('Escolha a camada da ação.');if(a.type==='music-play'&&!a.assetId&&!a.playlistId)throw new Error('Escolha uma música ou playlist.');if(a.type==='ambience'&&!a.ambienceId)throw new Error('Escolha o ambiente salvo.');if(a.type==='navigate'&&!a.pageId)throw new Error('Escolha uma página.');if(a.type==='message'&&!a.message?.trim())throw new Error('Escreva o lembrete.');}
    if(cue){cue.name=name;cue.actions=actions;}else{const value={id:uid('cue'),name,actions};scene.cues??=[];scene.cues.push(value);scene.triggers.push({id:uid('trigger'),name,cue:true,cueId:value.id,key:''});}
    ctx.commit();return back;
  }});
}
